  {name:"Pure White Dye",cat:"Special (non-craftable)",detail:"Wilmer, Provisioner's Shop in Timberton (Delesyia), 15 Silver (NICHT 1,50). Nicht craftbar; 1x auch Belohnung einer 'Restore the Abyss'-Mission der Quest The Abyss (Mission 1002824). Der Laden erscheint erst nach der Bohrturm-Questreihe des Bürgermeisters bzw. der Blackwater-Oil-Merchant-Guild-Kette (Cordelia).",loc:"Game8 (599343); VULKK",miss:true,conf:"high",color:"#FFFFFF",icon:"cd_assets/dyes/dye_pure-white.webp"},
  {name:"Shadow Grey Dye",cat:"Special (non-craftable)",detail:"Oliver (Camp-Dyer) im Greymane Camp, 15 Silver (questlog-Basispreis 1500 Kupfer), nicht craftbar; DE-Spielname „Dunkelgrau“ (identisch mit dem DE-Namen des Cloud Grey Dye); questlog nennt zusätzlich den Händler Colby (Ort nicht erfasst). Oliver kommt über die Greymane-Reihe Solid Foundation ins Camp, konkret über die Quest A Rumor at the Inksworth Bindery; Solid Foundation öffnet sich erst nach dem 3. Camp-Ausbau (Ende der Reihe Gathered Will). VULKK nennt alternativ einen Provisioner in Senia.",loc:"Raider King; VULKK",miss:true,conf:"high",color:"#6c757d",icon:"cd_assets/dyes/dye_shadow-grey.webp"},
  {name:"Black Dye",cat:"Special (non-craftable)",detail:"Back Alley Shop in Muiquun, südöstlich von Tommaso, 37,5 Silver laut Guides (questlog führt für den Händler Aris nur den Grundpreis 1500 Kupfer = 15 Silver; woher der Aufschlag stammt, ist ingame ungeprüft), nicht craftbar. DE-Spielname „Schwarz“. Händlername: questlog nennt Aris, Raider King/VULKK nennen Solan (Solan verkauft laut questlog das Bright Grey Dye). Erst nach Befreiung von Muiquun und der Lawless-Market-Schmuggler-Kette (Muiquun's Black Market).",loc:"Raider King; VULKK",miss:true,conf:"high",color:"#0d0d0d",icon:"cd_assets/dyes/dye_black.webp"},
  {name:"Grey Dye",cat:"Special (non-craftable)",detail:"Belohnung der Quest Brightening the Spirits (Nairas Scattered Embers, Hernand), nicht craftbar. Eigenständig vom Bright Grey Dye. Hinweis: Quellen verorten die Quest in Howling Hill, nicht in Hernand.",loc:"VULKK; Raider King",miss:true,conf:"medium",color:"#727b7d",icon:"cd_assets/dyes/dye_grey.webp"},
  {name:"Bright Grey Dye",cat:"Special (non-craftable)",detail:"Back Alley Shop (Solan) im Saltroad Camp, 33 Silver laut Raider King/GAMES.GG (questlog: Händler Solan, Grundpreis 1500 Kupfer = 15 Silver; DE-Spielname „Hellgraues Färbemittel“), nicht craftbar. Erst nach Räumen des Camps und Principles of the Saltroad Merchants. Getrennt vom regulären Grey Dye.",loc:"Raider King; GAMES.GG",miss:true,conf:"high",color:"#aeb4b8",icon:"cd_assets/dyes/dye_bright-grey.webp"},
  {name:"Silver Grey Dye",cat:"Special (non-craftable)",detail:"Norden, Provisioner's Shop in Kharonso (Südwest-Pailune), 15 Silver (allthings.how; questlog-Basispreis 1500 Kupfer, Händler Norden). Nicht craftbar; auch Belohnung der Mission 'Observe the adventurer constellation'. DE-Spielname „Silbergrau“. Farbwert aus dem questlog-Icon abgenommen (Näherung).",loc:"questlog.gg (Item 1001308); allthings.how",miss:false,conf:"medium",color:"#acb3b5",icon:"cd_assets/ql/assets/_sprites/itemicon_collection_prop_dyewater_0053.webp"},
  {name:"Medium Grey Dye",cat:"Special (non-craftable)",detail:"Fenton, Provisioner's Shop des St. Halssius's House of Healing (Demeniss; ConsolePulse), questlog-Basispreis 1500 Kupfer (15 Silver). Nicht craftbar. DE-Spielname „Mittelgrau“. Farbwert aus dem questlog-Icon abgenommen (Näherung).",loc:"questlog.gg (Item 1001324); ConsolePulse",miss:false,conf:"medium",color:"#949997",icon:"cd_assets/ql/assets/_sprites/itemicon_collection_prop_dyewater_0054.webp"},
  {name:"Cloud Grey Dye",cat:"Special (non-craftable)",detail:"Händler Olive (laut ConsolePulse im Tariv Provisioner's Shop nach der Quest The Light of Tariv; Einzelquelle), questlog-Basispreis 1500 Kupfer (15 Silver); auch Belohnung der Mission 'Head to the encampment to meet Barden'. Nicht craftbar. DE-Spielname „Dunkelgrau“ – identisch mit dem DE-Namen des Shadow Grey Dye (Verwechslungsgefahr). Farbwert aus dem questlog-Icon abgenommen (Näherung).",loc:"questlog.gg (Item 1001712); ConsolePulse",miss:false,conf:"medium",color:"#43474a",icon:"cd_assets/ql/assets/_sprites/itemicon_collection_prop_dyewater_0057.webp"},
  {name:"Dark Grey Dye",cat:"Special (non-craftable)",detail:"Händler Tobit (laut ConsolePulse im Odeck Provisioner's Shop nach dem Sieg über The Forgotten General; Einzelquelle), questlog-Basispreis 1500 Kupfer (15 Silver). Nicht craftbar. DE-Spielname „Düsteres Grau“. Farbwert aus dem questlog-Icon abgenommen (Näherung).",loc:"questlog.gg (Item 1001789); ConsolePulse",miss:false,conf:"medium",color:"#262828",icon:"cd_assets/ql/assets/_sprites/itemicon_collection_prop_dyewater_0059.webp"},
  {name:"Deep Grey Dye",cat:"Special (non-craftable)",detail:"Händler Ronan (laut ConsolePulse im Communal Training Grounds Back Alley Shop, spät in der Hernand-Back-Alley-Reihe; Einzelquelle; derselbe Händler führt laut questlog auch die Waffe Hollow Visage), questlog-Basispreis 1500 Kupfer (15 Silver). Nicht craftbar. DE-Spielname „Tiefes Grau“. Farbwert aus dem questlog-Icon abgenommen (Näherung).",loc:"questlog.gg (Item 1001749); ConsolePulse",miss:false,conf:"medium",color:"#323431",icon:"cd_assets/ql/assets/_sprites/itemicon_collection_prop_dyewater_0058.webp"}
