  {name:"Fruit Punch",cat:"Food — Fire Resistance",detail:"Günstigste verlässliche Feuerresistenz-Quelle. Rezept: 1 Berry + 1 Gerste + 1 Water = Health +140, Geist +12, Feuerresistenz Lv 4 für 1 Min. Billiger Top-up vor Feuer-Bossen.",loc:"Feld-Kochtopf. Quelle: VGC",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_hwachae_0001.webp",lead:"Günstigste verlässliche Feuerresistenz-Quelle.",fx:[["hp","Health","+140"],["spirit","Spirit","+12"],["fire","Fire Resistance","Lv 4"],["dur","Dauer","1 Min"]],recipe:[["1","Berry"],["1","Barley"],["1","Water"]],station:"Feld-Kochtopf",src:["VGC"]},
  {name:"Pan-Fried Marinated Meat",cat:"Food — Fire Resistance",detail:"Starkes gegrilltes Feuerresistenz-Gericht. Rezept: 3 Meat + 2 Berry + 2 Zwiebel (oder Flachs/Gurke/Rübe/Rote Beete) + 3 Speiseöl = Health +320 (VGC nennt +260), Geist +24, Feuerresistenz Lv 4 für 1 Min. Gut für Feuer-Bosse und Lava-/Abyss-Zonen.",loc:"Feld-Grill an jedem Lagerfeuer. Quelle: VGC",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_bulgogi_0001.webp",lead:"Starkes gegrilltes Feuerresistenz-Gericht.",fx:[["hp","Health","+320"],["spirit","Spirit","+24"],["fire","Fire Resistance","Lv 4"],["dur","Dauer","1 Min"]],recipe:[["3","Meat"],["2","Berry"],["2","Onion","oder Flax/Cucumber/Turnip/Beet"],["3","Cooking Oil"]],alt:"VGC nennt +260",station:"Feld-Grill an jedem Lagerfeuer",src:["VGC"]},
  {name:"Battered Seafood",cat:"Food — Fire Resistance",detail:"Gegrillte Feuerresistenz- und Geist-Option. Rezept: 2 Fish (oder 4 Fischfilet) + 2 Zwiebel (oder Flachs/Gurke/Rübe/Rote Beete) + 2 Egg + 3 Speiseöl = Health +320 (VGC und thegameswiki nennen +260), Geist +24, Feuerresistenz Lv 4 für 1 Min.",loc:"Feld-Grill. Quelle: VGC",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_seafoodpancake_0001.webp",lead:"Gegrillte Feuerresistenz- und Geist-Option.",fx:[["hp","Health","+320"],["spirit","Spirit","+24"],["fire","Fire Resistance","Lv 4"],["dur","Dauer","1 Min"]],recipe:[["2","Fish","oder 4 Fish Fillet"],["2","Onion","oder Flax/Cucumber/Turnip/Beet"],["2","Egg"],["3","Cooking Oil"]],alt:"VGC und thegameswiki nennen +260",station:"Feld-Grill",src:["VGC"]},
  {name:"Vegetable Rice Cake",cat:"Food — Fire Resistance",detail:"Bestes Feuerresistenz-Gericht rein aus farmbarem Gemüse und Ei. Rezept: 4 Zwiebel (oder Flachs/Gurke/Rübe/Rote Beete) + 2 Berry + 1 Egg + 2 Salz = Health +300 (Fextralife nennt +240), Geist +22, Feuerresistenz Lv 4 für 1 Min.",loc:"Feld-Grill. Quelle: VGC",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_vegetable_tteok_0001.webp",lead:"Bestes Feuerresistenz-Gericht rein aus farmbarem Gemüse und Ei.",fx:[["hp","Health","+300"],["spirit","Spirit","+22"],["fire","Fire Resistance","Lv 4"],["dur","Dauer","1 Min"]],recipe:[["4","Onion","oder Flax/Cucumber/Turnip/Beet"],["2","Berry"],["1","Egg"],["2","Salt"]],alt:"Fextralife nennt +240",station:"Feld-Grill",src:["VGC"]},
  {name:"Salt-Roasted Bird Meat",cat:"Food — Fire Resistance",detail:"Günstigste frühe Feuerresistenz. Rezept: 1 Vogelfleisch + 1 Salz = Health +120, Feuerresistenz Lv 2 für 30 Sek. Schneller Top-up aus gejagten Vögeln.",loc:"Feld-Grill. Quelle: VGC",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_chicken_0002.webp",lead:"Günstigste frühe Feuerresistenz.",fx:[["hp","Health","+120"],["fire","Fire Resistance","Lv 2"],["dur","Dauer","30 Sek."]],recipe:[["1","Bird Meat"],["1","Salt"]],station:"Feld-Grill",src:["VGC"]},
  {name:"Battered Harvest Roll",cat:"Food — Fire Resistance",detail:"Hochwertiges Feuerresistenz-Grillgericht. Rezept: 2 Getreiderolle + 1 Deftiges Fleisch + 2 Egg + 2 Speiseöl. Basis ca. Geist +62 und Feuerresistenz +6 (ca. 1 Min 30 Sek) laut Item-Datenbanken; die Hearty-Stufe wird mit ca. +1000 HP / +92 Geist / Feuerresistenz +6 angegeben (Einzelquelle, als ungefähr behandeln). HP skaliert mit Stufe, Resistance bleibt fix.",loc:"Rezept bei einem Inn-Innkeeper lernbar (genannt: Delesyia Inn). Quelle: Gamer Guides, gaming.tools; Hearty-Werte method.gg",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_egg_gimbap_0001.webp",lead:"Hochwertiges Feuerresistenz-Grillgericht.",fx:[["spirit","Spirit","ca. +62"],["fire","Fire Resistance","+6"],["dur","Dauer","ca. 1 Min 30 Sek"]],recipe:[["2","Harvest Roll"],["1","Fine Meat"],["2","Egg"],["2","Cooking Oil"]],alt:"Hearty-Stufe wird mit ca. +1000 HP / +92 Spirit / Fire Resistance +6 angegeben (Einzelquelle, als ungefähr behandeln)",learn:"Rezept bei einem Inn-Innkeeper lernbar (genannt: Delesyia Inn).",src:["Gamer Guides","gaming.tools","method.gg"]},
  {name:"Freya's Elixir",cat:"Elixir — Angriff/Tempo",detail:"Wichtigstes OFFENSIV-Elixier vor Bossen. Tier-Leiter: Lesser = Attack +5 (5 Min); Standard = Attack +7 (10 Min); Greater = Attack +10 (15 Min). Am Cauldron gebraut (Attack-Reagenz + Katalysator + Leere Flasche).",loc:"Formeln über Welt-Loot/Händler/Nebenquests. Die Forschung 'Plant Combination Research' (Shai-Apotheker in Pororin) schaltet laut Beschreibung diverse Elixier-Rezepte frei — welche genau, ist nicht dokumentiert. Die Mission 'Defeat the Crimson Nightmare' (Quest 'Anhaltende Sorge') gibt 1x Freyas Elixier (dazu 2x Apollonia's Lesser und 2x Meliara's Lesser), 'Head to Hernand' (Quest 'Unknown Space') ein weiteres; fertig auch bei Conrad/Vincent für 300 Kupfer. Quelle: questlog-API, gaming.tools",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_potion_0004_index01_r.webp",lead:"Wichtigstes OFFENSIV-Elixier vor Bossen.",tiers:[["Lesser","Attack +5","5 Min"],["Standard","Attack +7","10 Min"],["Greater","Attack +10","15 Min"]],recipe:[["","Attack-Reagenz"],["","Katalysator"],["","Empty Bottle"]],station:"Cauldron",learn:"Formeln über Welt-Loot/Händler/Nebenquests.",buy:"bei Conrad/Vincent für 300 Kupfer",src:["questlog-API","gaming.tools"]},
  {name:"Meliara's Lesser Elixir",cat:"Elixir — Angriff/Tempo",detail:"Max Health +75 und Angriffstempo Lv 1 für 5 Min - anhaltende Überlebensfähigkeit plus Offense aus dem Basis-Kessel. Rezept: 2x Lesser-Health-Reagenz + 1x Lesser-Katalysator + 1x Leere Flasche. Greater-Stufe gibt Max Health +225 / Angriffstempo Lv 3 für 15 Min.",loc:"Formel bei Schlammgrat-Hütte (nördlich von Pororin Woods, Hernand; Schiebebild-Rätsel lösen). Quelle: TheGamer, gaming.tools",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_potion_0004_index06_r.webp",lead:"Anhaltende Überlebensfähigkeit plus Offense aus dem Basis-Kessel.",tiers:[["Lesser","Max Health +75 / Attack Speed Lv 1","5 Min"],["Greater","Max Health +225 / Attack Speed Lv 3","15 Min"]],recipe:[["2x","Lesser-Health-Reagenz"],["1x","Lesser-Katalysator"],["1x","Empty Bottle"]],station:"Cauldron",learn:"Formel bei Schlammgrat-Hütte (nördlich von Pororin Woods, Hernand; Schiebebild-Rätsel lösen).",src:["TheGamer","gaming.tools"]},
  {name:"Apollonia's Elixir",cat:"Elixir — Verteidigung",detail:"Defensive Named-Elixier-Linie - Defense Up, KEIN Offensiv-Buff. Tier-Leiter: Lesser = Defense +10 (5 Min); Common/Standard = Defense +20 (10 Min); Superior/Greater = Defense +30 (15 Min). Am Cauldron gebraut (Defense-Reagenz + Katalysator + Leere Flasche).",loc:"Formel bei Bari für 1000 Kupfer bzw. Belohnung der Mission 'Talk to the witch at the Sanctum of Veneration' (Quest Hexe der Demut); fertig bei Conrad für 300 Kupfer. Greater-Stufe: Formel bei Areciel (Mission 'Talk to the witch at the Sanctum of Oblation'). Die Forschung 'Plant Combination Research' (Shai-Apotheker in Pororin) schaltet laut Beschreibung diverse Elixier-Rezepte frei — welche genau, ist nicht dokumentiert. Quelle: questlog-API, gaming.tools",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_potion_0004_index05_r.webp",lead:"Defensive Named-Elixier-Linie - Defense Up, KEIN Offensiv-Buff.",tiers:[["Lesser","Defense +10","5 Min"],["Common/Standard","Defense +20","10 Min"],["Superior/Greater","Defense +30","15 Min"]],recipe:[["","Defense-Reagenz"],["","Katalysator"],["","Empty Bottle"]],station:"Cauldron",learn:"Formel bei Bari für 1000 Kupfer bzw. Belohnung der Mission 'Talk to the witch at the Sanctum of Veneration' (Quest Hexe der Demut).",buy:"bei Conrad für 300 Kupfer",src:["questlog-API","gaming.tools"]},
  {name:"Haiden's Lesser Elixir",cat:"Elixir — Spirit/Stamina",detail:"Ignoriert für 4 Sekunden den Geist-Verbrauch - erlaubt eine kurze Kette aus Geist-kostenden Spezialmoves. Kessel-Rezept: 2x niedriges Reagenz + 1x Lesser Catalyst (Eisenerz, Kupfererz, Stone o.ä.) + 1x Leere Flasche.",loc:"Formel in Hernand, im Haus mit Trank- und Alchemiegläsern am Eingang; sie liegt auf dem Tisch in der Raummitte. Quelle: Fextralife; Rezeptwerte: gaming.tools, TheGamer",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_potion_0004_index09_r.webp",lead:"Erlaubt eine kurze Kette aus Geist-kostenden Spezialmoves.",fx:[["spirit","Spirit-Verbrauch","ignoriert"],["dur","Dauer","4 Sekunden"]],recipe:[["2x","niedriges Reagenz"],["1x","Lesser Catalyst","Iron Ore, Copper Ore, Stone o.ä."],["1x","Empty Bottle"]],station:"Cauldron",learn:"Formel in Hernand, im Haus mit Trank- und Alchemiegläsern am Eingang; sie liegt auf dem Tisch in der Raummitte.",src:["Fextralife","gaming.tools","TheGamer"]},
  {name:"Astrid's Lesser Elixir",cat:"Elixir — Spirit/Stamina",detail:"Ignoriert für 4 Sekunden den Ausdauer-Verbrauch - ein Schub unbegrenztes Sprinten/Ausweichen/Repositionieren. Kessel-Rezept: 2x niedriges Ausdauer-Reagenz + 1x Lesser Catalyst + 1x Leere Flasche.",loc:"Formel bei Händler Ladolph für 500 Kupfer (im Back-Alley-Shop in Pailune nach einem Punkt der Hauptstory laut TheGamer); das fertige Elixier ist Belohnung der Mission 'Return the relic to Arkin'. Quelle: questlog-API, TheGamer, gaming.tools",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_potion_0004_index12_r.webp",lead:"Ein Schub unbegrenztes Sprinten/Ausweichen/Repositionieren.",fx:[["stam","Stamina-Verbrauch","ignoriert"],["dur","Dauer","4 Sekunden"]],recipe:[["2x","niedriges Stamina-Reagenz"],["1x","Lesser Catalyst"],["1x","Empty Bottle"]],station:"Cauldron",learn:"Formel bei Händler Ladolph für 500 Kupfer (im Back-Alley-Shop in Pailune nach einem Punkt der Hauptstory laut TheGamer).",src:["questlog-API","TheGamer","gaming.tools"]},
  {name:"Palmar Pill",cat:"Elixir — Wiederbelebung",detail:"Selbst-Wiederbelebung: bei Tod sofortiges Revive mit 30% der max. Health für einen weiteren Versuch - wichtiger Panik-Knopf für harte Bosse. Kessel-Rezept: 2x Water + 15x Medizinische Kräuter derselben Sorte (31 Sorten kommen in Frage).",loc:"Formel in der Schattenflüsterhöhle nördlich von Hernand-Stadt (Felsspalte in der Klippe), auf einem Tisch bei der Hexe Sylvia; die Höhle gehört zur Quest 'Verfeinerte Kraft' (ab Kapitel 3). Laut questlog außerdem Belohnung der Missionsschritte 'Visit Master Du', 'Fliegende Festung Orbian', 'Assess the situation with your comrades' und 'Stelle den Abyss wieder her' (Nest der Tapferkeit) sowie Tariv-Sorcerer-Drop. Die Pille selbst auch bei Lacey (Laceys Geheimladen) für 360 Kupfer. Quelle: game8, gaming.tools, questlog-API",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_cd_t0000_revivalpill_0002.webp",lead:"Wichtiger Panik-Knopf für harte Bosse.",fx:[["rev","Revive mit","30% der max. Health"]],recipe:[["2x","Water"],["15x","Medicinal Herb derselben Sorte","31 Sorten kommen in Frage"]],station:"Cauldron",learn:"Formel in der Schattenflüsterhöhle nördlich von Hernand-Stadt (Felsspalte in der Klippe), auf einem Tisch bei der Hexe Sylvia; die Höhle gehört zur Quest 'Verfeinerte Kraft' (ab Kapitel 3).",buy:"bei Lacey (Laceys Geheimladen) für 360 Kupfer",src:["game8","gaming.tools","questlog-API"]},
  {name:"Refined Palmar Pill",cat:"Elixir — Wiederbelebung",detail:"Verbesserte Selbst-Wiederbelebung: Revive mit 100% der max. Health (statt 30% bei der normalen Kraftfaust-Kräuterpastille) - großer Überlebens-Item für Boss-Kämpfe. Kessel-Rezept: 1x Water + 1x Kraftfaustblatt + 1x Kraftfaustkäfer + 1x High-Grade Medicinal Herb (Ginseng, Langhorn oder Bärengallenblase).",loc:"Formel: Belohnung der Mission 'Raccos Anfrage' (Schritt 'Deliver the shovel', Quest Geschichten der pailunischen Händler) sowie sehr seltener Zufallsdrop von der Zauberin aus Tariv; der kursierende Fundort 'Asketenruh' (Abyss, Kapitel 9) ist unbelegt. Die Pille selbst bei Lacey (Laceys Geheimladen) für 1080 Kupfer, aus seltenen Drops, der Dispatch-Mission 'Entsendung zu den Fernhain-Ruinen' und Truhen. Quelle: gaming.tools, questlog-API",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_cd_t0000_revivalpill_0001.webp",lead:"Großer Überlebens-Item für Boss-Kämpfe.",fx:[["rev","Revive mit","100% der max. Health"]],recipe:[["1x","Water"],["1x","Palmar Leaf"],["1x","Palmar Beetle"],["1x","High-Grade Medicinal Herb","Ginseng, Long Horn oder Bear's Gallbladder"]],station:"Cauldron",learn:"Formel: Belohnung der Mission 'Raccos Anfrage' (Schritt 'Deliver the shovel', Quest Geschichten der pailunischen Händler) sowie sehr seltener Zufallsdrop von der Zauberin aus Tariv.",buy:"bei Lacey (Laceys Geheimladen) für 1080 Kupfer",src:["gaming.tools","questlog-API"]}
